/**
 * A server-paged, server-sorted, filterable record table over `useEntityQuery`. Page, sort and
 * filters live in the URL (`useQueryState`), so Back, Forward and a copied link restore the view;
 * the previous page stays on screen while the next one loads. Render kit `Select` and `Input`
 * controls inside `FilterBar` and write their values to `filters` as `{ field, operator, value }`.
 */
import { createRoot } from 'react-dom/client';
import { SurfaceApp, Table, parseAsEnum, parseAsFilters, parseAsInteger, parseAsString, useEntityQuery, useQueryState } from '@cynap/surface-sdk';

import './styles.css';

/** The org's entity type and the columns to show. Replace both. */
const ENTITY_TYPE = 'REPLACE_WITH_ENTITY_TYPE';
const COLUMNS = [
  { accessorKey: 'name', header: 'Name' },
  { accessorKey: 'stage', header: 'Stage' },
  { accessorKey: 'updated_at', header: 'Updated' },
];
const PAGE_SIZE = 25;

function Records() {
  const [page, setPage] = useQueryState('page', parseAsInteger, { defaultValue: 1, history: 'push' });
  const [sort, setSort] = useQueryState('sort', parseAsString);
  const [direction, setDirection] = useQueryState('dir', parseAsEnum(['asc', 'desc'] as const), { defaultValue: 'asc' });
  const current = Math.max(1, page ?? 1);
  const [filters] = useQueryState('filters', parseAsFilters, { defaultValue: [] });
  const records = useEntityQuery(ENTITY_TYPE, {
    filters,
    page: current,
    pageSize: PAGE_SIZE,
    ...(sort ? { sort: { field: sort, direction: direction ?? 'asc' } } : {}),
  });

  return (
    <main className="tpl-page">
      <Table
        columns={COLUMNS}
        data={records.data?.rows ?? null}
        isLoading={records.state === 'loading'}
        error={records.state === 'error' ? new Error('The records could not be loaded.') : null}
        onRetry={records.refetch}
        pagination={{ page: current, pageSize: PAGE_SIZE, total: records.data?.total ?? records.data?.rows.length ?? 0 }}
        onPageChange={(next) => setPage(next)}
        onSortChange={(next) => {
          setSort(next ? next.field : null);
          setDirection(next ? next.direction : null);
          setPage(1);
        }}
      />
    </main>
  );
}

const root = document.getElementById('root');
if (root) {
  createRoot(root).render(
    <SurfaceApp info={{ name: 'record-table', version: '1.0.0' }}>
      <Records />
    </SurfaceApp>
  );
}

